let activeUserId='device-preview';
let swipeCount=1,swipeSlots=[];try{const stored=Number(localStorage.getItem('debtfreelately-swipe-count'));if(Number.isInteger(stored)&&stored>=1&&stored<=5)swipeCount=stored;}catch{}
