const $=s=>document.querySelector(s), money=n=>new Intl.NumberFormat(t('en-AU','vi-VN','ko-KR'),{style:'currency',currency:'VND',maximumFractionDigits:0}).format(n), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const samples=[{id:'demo-1',name:'Minh Anh',city:'TP. Hồ Chí Minh',category:'Sinh hoạt',title:'Một khoảng thở để bắt đầu lại.',story:'Sau khi mất việc, mình dùng khoản vay nhỏ để trang trải tiền nhà và sinh hoạt cho hai mẹ con. Mình đã có công việc mới, nhưng khoản nợ cũ vẫn khiến mỗi tháng trở nên chật vật.\n\nMình đang cố gắng từng ngày. Một chút đồng hành lúc này sẽ giúp mình ổn định lại cuộc sống và có thời gian dành cho con.',amount:18500000,pledged:0,sample:true},{id:'demo-2',name:'Hoàng Nam',city:'Đà Nẵng',category:'Y tế',title:'Để ba yên tâm tiếp tục điều trị.',story:'Chi phí điều trị của ba đến bất ngờ, mình phải vay để lo viện phí. Mình đang làm thêm ngoài giờ để trả dần, nhưng vẫn cần một chút giúp đỡ để vượt qua giai đoạn này.',amount:32000000,pledged:0,sample:true},{id:'demo-3',name:'Thu Hà',city:'Hà Nội',category:'Học tập',title:'Mình muốn viết tiếp giấc mơ giảng đường.',story:'Mình là sinh viên năm cuối, vừa học vừa làm để tự trang trải. Khoản vay học phí là điều mình đang lo nhất. Mình mong có thể hoàn thành kỳ học cuối và tìm một công việc ổn định.',amount:12000000,pledged:0,sample:true},{id:'demo-4',name:'Quốc Bảo',city:'Cần Thơ',category:'Sinh hoạt',title:'Dựng lại góc sửa xe nhỏ của mình.',story:'Tiệm sửa xe nhỏ là nguồn thu nhập chính của gia đình. Sau một thời gian phải nghỉ việc vì tai nạn, mình đang quay lại làm và cần giải quyết khoản nợ sinh hoạt tích lại.',amount:9500000,pledged:0,sample:true}];
const initial=()=>({posts:structuredClone(samples),saved:[],skipped:[],pledges:[],role:'Bros'});let state=initial(),storageOK=true;
try{const raw=JSON.parse(localStorage.getItem('debtfreelately-v1'));if(raw&&Array.isArray(raw.posts)&&Array.isArray(raw.saved)&&Array.isArray(raw.skipped)&&Array.isArray(raw.pledges)){state=raw;state.posts=raw.posts.filter(p=>p&&typeof p.id==='string'&&typeof p.name==='string'&&typeof p.title==='string'&&typeof p.story==='string'&&Number.isFinite(p.amount)&&Number.isFinite(p.pledged));}}catch{storageOK=false;}
let approvedPosts=[];
const allPosts=()=>[...state.posts.filter(p=>p.sample||p.mine).map(localizeSample),...approvedPosts];
let view='discover',category='Tất cả',query='',lastSkipped=null,current=null;const categories=['Tất cả','Sinh hoạt','Y tế','Học tập','Khác'];
function persist(){try{localStorage.setItem('debtfreelately-v1',JSON.stringify(state));return true;}catch{storageOK=false;toast(t("Changes couldn't be saved to this device. They'll last for this session only.", "Không lưu được trên thiết bị. Thay đổi chỉ tồn tại trong phiên này.", "변경 사항을 기기에 저장하지 못했습니다. 현재 세션에서만 유지됩니다."));return false;}}
let timer;function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function modal(html){delete $('#modal').dataset.adCommunity;$('#modal-body').innerHTML=html;$('#modal').showModal();}function close(){$('#modal').close();}$('#close-modal').onclick=close;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});
function filtered(){return filterPosts(allPosts(),{category,query,skipped:state.skipped}).filter(p=>!p.mine&&(p.serverCard||p.pledged<p.amount));}
function empty(title,text,button='',action=''){return `<div class="empty"><div class="symbol">✳</div><h2>${title}</h2><p>${text}</p>${button?`<button class="dark" data-action="${action}">${button}</button>`:''}</div>`;}
function render(){document.body.dataset.adView=view;document.body.classList.toggle('swipe-page',view==='discover');document.body.classList.toggle('saved-page',view==='saved');$('#profile-nav').hidden=false;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#saved-count').textContent=state.saved.length+Object.keys(previewStore()).length;$('#role-name').textContent=state.role==='Bros'?t("You're a Bro", "Bạn là một Bros", "Bros로 참여 중입니다"):t("You're a Broke member", "Bạn là Broke", "Broke로 참여 중입니다");$('#categories').innerHTML=categories.map(c=>`<button data-category="${c}" class="${category===c?'active':''}">${categoryLabel(c)}</button>`).join('');$('.toolbar').hidden=view!=='discover'&&view!=='saved';const titles={discover:[`${t("One swipe.", "Một lần quẹt.", "한 번의 스와이프.")}<br><span>${t("A fresh start.", "Một khởi đầu mới.", "새로운 시작.")}</span>`,`${t("There's a story behind every debt. Listen, connect,", "Phía sau mỗi khoản nợ là một câu chuyện. Lắng nghe, kết nối", "모든 빚에는 사연이 있습니다. 이야기를 듣고 소통하며")}<br class="desktop"> ${t("and help someone move forward in your own way.", "và giúp ai đó bước tiếp — theo cách của bạn.", "나만의 방식으로 누군가의 새 출발을 도와주세요.")}`],saved:[`${t("Stories you want", "Những câu chuyện", "간직하고 싶은")}<br><span>${t("to keep.", "bạn muốn giữ lại.", "이야기.")}</span>`,t("A small connection today can grow into lasting support.", "Một kết nối nhỏ hôm nay có thể trở thành sự đồng hành ngày mai.", "오늘의 작은 인연이 내일의 든든한 응원이 될 수 있습니다.")],pledges:[`${t("Your kindness,", "Sự tử tế,", "당신의 따뜻한 마음을")}<br><span>${t("all in one place.", "được ghi nhận.", "한곳에 모았습니다.")}</span>`,t("Track your pledges. No money has been transferred through the app.", "Theo dõi cam kết của bạn. Chưa có tiền được chuyển qua ứng dụng.", "지원 약속을 확인하세요. 앱을 통해 송금된 금액은 없습니다.")],mine:[`${t("Your story.", "Câu chuyện của bạn.", "여러분의 이야기.")}<br><span>${t("A new opportunity.", "Một cơ hội mới.", "새로운 기회.")}</span>`,t("Share what you're going through and manage your posts.", "Chia sẻ điều bạn đang trải qua và quản lý các bài đăng của mình.", "겪고 있는 일을 나누고 게시물을 관리하세요.")]};$('#page-title').innerHTML=titles[view][0];$('#page-description').innerHTML=titles[view][1];
if(view==='discover')renderDeck();if(view==='saved')renderSavedCards();if(view==='mine')renderList(state.posts.filter(p=>p.mine),'mine');if(view==='pledges')renderPledges();}
function projectedPost(p){if(p.serverCard)return p.serverCard;const settings=p.privacy||(p.sample?{realName:true,age:true,location:true,photo:true,publicStory:true}:defaultPrivacy());return publicCard([{title:p.title,story:p.story}],settings,{name:p.name,nickname:p.nickname||'Broke_'+p.id.slice(0,6),age:p.age||(p.sample&&p.id==='demo-1'?25:undefined),location:p.city,photo:p.photo||(p.sample&&p.id==='demo-1'?'assets/demo-minh-anh.png':undefined)});}
function renderDeck(){const posts=filtered();const allowed=new Set(posts.map(p=>p.id));swipeSlots=Array.from({length:swipeCount},(_,i)=>allowed.has(swipeSlots[i])?swipeSlots[i]:null);for(let i=0;i<swipeSlots.length;i++)if(!swipeSlots[i])swipeSlots[i]=posts.find(p=>!swipeSlots.includes(p.id))?.id||null;const visible=swipeSlots.map(id=>posts.find(p=>p.id===id)).filter(Boolean);current=visible[0];$('#content').innerHTML=`<div class="discover-layout ${swipeCount>1?"is-multi":""}">${discoverIntro()}<section class="discover-deck"><section class="swipe-stage"><div class="swipe-count-control"><label for="swipe-card-count">${t("Cards per swipe", "Số lượng thẻ quẹt trong một lần", "한 번에 볼 카드 수")}<small>${t("Up to five cards · Each person appears once", "Tối đa 5 thẻ · Mỗi người chỉ xuất hiện một lần", "최대 5장 · 한 사람당 한 번만 표시")}</small></label><select id="swipe-card-count" aria-label="${t("Cards per swipe", "Số lượng thẻ quẹt trong một lần", "한 번에 볼 카드 수")}">${[1,2,3,4,5].map(n=>`<option value="${n}" ${swipeCount===n?'selected':''}>${t(`${n} ${n===1?'card':'cards'}`, `${n} thẻ`, `${n}장`)}</option>`).join('')}</select></div>${visible.length?`<div class="swipe-decks" data-count="${swipeCount}">${visible.map(p=>`<div class="deck-swipe" data-card-id="${esc(p.id)}">${discoveryCard(projectedPost(p),{post:p,saved:state.saved.includes(p.id)})}</div>`).join('')}</div><p class="swipe-queue-note">${visible.length<swipeCount?t(`${visible.length} matching ${visible.length===1?'card':'cards'} left to show. `, `Còn ${visible.length} thẻ phù hợp để hiển thị. `, `조건에 맞는 카드가 ${visible.length}장 남았습니다. `):''}${swipeCount>1?t("On your phone, swipe sideways to see the selected cards.", "Trên điện thoại, vuốt ngang để xem các thẻ đã chọn.", "휴대전화에서는 좌우로 밀어 선택한 카드를 확인하세요."):''}</p>`:empty(t("You're all caught up!", "Bạn đã xem hết rồi!", "모든 카드를 확인했어요!"),t("Revisit stories you skipped to keep exploring.", "Xem lại các câu chuyện đã bỏ qua để tiếp tục khám phá.", "건너뛴 이야기를 다시 둘러보세요."),t("Review cards", "Xem lại các thẻ", "카드 다시 보기"),'reset')}</section><div class="discover-carousel-footer"><button data-action="undo" aria-label="${t('Go back to the last skipped card', 'Quay lại thẻ vừa bỏ qua', '마지막으로 건너뛴 카드로 돌아가기')}" ${lastSkipped?'':'disabled'}>‹</button><span>${t(`${visible.length} of ${posts.length} ${posts.length===1?'story':'stories'}`, `${visible.length} / ${posts.length} câu chuyện`, `이야기 ${visible.length} / ${posts.length}개`)}</span><button data-action="skip" aria-label="${t('See the next person', 'Xem người tiếp theo', '다음 사람 보기')}" ${current?'':'disabled'}>›</button></div></section>${discoverCommunity({stories:allPosts().filter(p=>!p.mine).length,saved:getRemainingSaved().length})}</div>`;$('#swipe-card-count').onchange=event=>{const count=Number(event.target.value);if(!Number.isInteger(count)||count<1||count>5)return;swipeCount=count;try{localStorage.setItem('debtfreelately-swipe-count',String(count));}catch{}renderDeck();};document.querySelectorAll('.swipe-decks .deck-swipe').forEach(card=>{let start=null;card.addEventListener('pointerdown',event=>{if(event.target.closest('button')||(swipeCount>1&&window.matchMedia('(max-width:620px)').matches))return;start={x:event.clientX,y:event.clientY};});card.addEventListener('pointerup',event=>{if(!start)return;const dx=event.clientX-start.x,dy=event.clientY-start.y;start=null;if(Math.abs(dx)>70&&Math.abs(dx)>Math.abs(dy)*1.5){if(dx<0)skip(card.dataset.cardId);else showCardDetails(card.dataset.cardId);}});card.addEventListener('pointercancel',()=>start=null);});}
function previewStore(){try{return JSON.parse(localStorage.getItem(savedPreviewsKey(activeUserId))||'{}');}catch{return {};}}
function cardById(id){if(id.startsWith('preview:'))return previewStore()[id.slice(8)]||null;const p=allPosts().find(p=>p.id===id);return p?projectedPost(p):null;}
function showCardDetails(id){const card=cardById(id);if(!card)return;showSupportChoices({modal,close,pay:()=>showSupportMessageStep({id,name:card.name,modal,toast}),contact:()=>openCardConversation({id,name:card.name,title:card.debts.map(d=>d.title).join(' · ')})});}
function openSavedCards(){document.body.classList.remove('broke-mode','messages-mode','debts-mode','card-wizard-mode');category='Tất cả';query='';view='saved';render();window.scrollTo(0,0);}
function getRemainingSaved(){const cards=[...allPosts().filter(p=>state.saved.includes(p.id)).map(p=>({id:p.id,card:projectedPost(p),sample:p.sample})),...Object.entries(previewStore()).map(([id,card])=>({id:'preview:'+id,card}))];return remainingSavedCards(cards,state.supportTransactions||[],activeUserId);}
function renderSavedCards(){const items=getRemainingSaved();$('#content').innerHTML=items.length?`<section class="saved-only-grid" aria-label="${t("Saved cards you haven't supported yet", "Các thẻ đã lưu chưa được bạn giúp đỡ", "아직 지원하지 않은 저장 카드")}">${items.map(item=>`<div class="saved-card-item">${debtCardHTML(item.card,{id:item.id,saved:true,sample:item.sample})}</div>`).join('')}</section>`:empty(t("No cards are waiting for you yet.", "Chưa có thẻ đang chờ bạn.", "아직 지원을 기다리는 카드가 없습니다."),t("Saved cards you haven't supported yet will appear here.", "Các thẻ đã lưu và chưa được bạn giúp đỡ sẽ xuất hiện tại đây.", "저장한 카드 중 아직 지원하지 않은 카드가 여기에 표시됩니다."),t("Find a Broke member", "Tìm Broke", "Broke 회원 찾기"),'discover');}
function renderList(posts,kind){if(!posts.length){$('#content').innerHTML=empty(kind==='mine'?t("Your story starts here.", "Câu chuyện của bạn bắt đầu ở đây.", "여러분의 이야기는 여기서 시작됩니다."):t("There are no stories yet. ", "Chưa có câu chuyện nào. ", "아직 이야기가 없습니다."),kind==='mine'?t("Post under a nickname. Keep account numbers and personal documents private.", "Đăng bài bằng biệt danh. Không chia sẻ số tài khoản hoặc giấy tờ cá nhân.", "닉네임으로 게시하세요. 계좌번호나 개인 서류는 공개하지 마세요."):t("Select the star on a card to save the story.", "Nhấn ngôi sao trên thẻ để lưu một câu chuyện.", "카드의 별을 눌러 이야기를 저장하세요."),kind==='mine'?t("Write your story", "Viết câu chuyện", "이야기 쓰기"):t("Explore now", "Khám phá ngay", "지금 둘러보기"),kind==='mine'?'new':'discover');return;}$('#content').innerHTML=posts.map(p=>`<article class="list-card"><small>${esc(categoryLabel(p.category))} · ${p.sample?t("Sample profile", "Hồ sơ mẫu", "예시 프로필"):t("Unverified", "Chưa xác minh", "미인증")}</small><h3>${esc(p.title)}</h3><small>${esc(p.name)}</small><div class="row"><strong>${money(p.amount)}</strong><button class="text-button" data-action="detail" data-id="${esc(p.id)}">${t("Read the story ↗", "Xem câu chuyện ↗", "이야기 읽기 ↗")}</button></div><div class="progress"><div style="width:${Math.min(100,p.pledged/p.amount*100)}%"></div></div><small>${money(p.pledged)} ${t("pledged · Payment pending", "cam kết · Chưa thanh toán", "지원 약속 · 미결제")}</small><div class="row">${kind==='mine'?`<button class="text-button" data-action="edit" data-id="${esc(p.id)}">${t("Edit post", "Sửa bài", "게시물 수정")}</button><button class="text-button danger" data-action="delete" data-id="${esc(p.id)}">${t("Delete post", "Xóa bài", "게시물 삭제")}</button>`:`<button class="text-button" data-action="save" data-id="${esc(p.id)}">${t("Remove from saved", "Bỏ lưu", "저장 해제")}</button><button class="dark" data-action="help" data-id="${esc(p.id)}">${t("I'd like to help ♡", "Tôi muốn giúp ♡", "도움을 주고 싶어요 ♡")}</button>`}</div></article>`).join('');}
function renderPledges(){if(!state.pledges.length){$('#content').innerHTML=empty(t("A little help can go a long way.", "Một chút giúp đỡ, một ý nghĩa lớn.", "작은 도움이 큰 힘이 됩니다."),`${t("Your confirmed pledges will appear here.", "Cam kết bạn xác nhận sẽ xuất hiện ở đây.", "확인한 지원 약속이 여기에 표시됩니다.")}<br>${t("These amounts haven't been paid.", "Đây chưa phải khoản tiền đã gửi.", "아직 결제된 금액은 아닙니다.")}`,t("Find a story", "Tìm câu chuyện", "이야기 찾기"),'discover');return;}$('#content').innerHTML=`<div class="stats"><div class="stat"><small>${t("Total pledged", "Tổng cam kết", "총 지원 약속 금액")}</small><strong>${money(state.pledges.reduce((s,p)=>s+p.amount,0))}</strong></div><div class="stat"><small>${t("Number of pledges", "Số lần đồng hành", "지원 약속 횟수")}</small><strong>${state.pledges.length}</strong></div></div>`+state.pledges.map(p=>`<article class="list-card"><small>${new Date(p.date).toLocaleDateString(t('en-AU','vi-VN','ko-KR'))} · ${t('Unpaid', 'Chưa thanh toán', '미결제')}</small><h3>${esc(allPosts().find(post=>post.sample&&post.id===p.postId)?.title||p.title)}</h3><div class="row"><strong>${money(p.amount)}</strong><button class="text-button danger" data-action="cancel" data-id="${esc(p.id)}">${t("Cancel pledge", "Hủy cam kết", "지원 약속 취소")}</button></div></article>`).join('');}
function skip(id=current?.id){if(!id||state.skipped.includes(id))return;lastSkipped=id;state.skipped.push(id);persist();const card=[...document.querySelectorAll('.deck-swipe')].find(c=>c.dataset.cardId===id);card?.classList.add('out-left');setTimeout(render,200);}
function save(id){state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];try{localStorage.setItem(savedIdsKey(activeUserId),JSON.stringify(state.saved));}catch{toast(t("Changes couldn't be saved to this device.", "Không lưu được thay đổi trên thiết bị.", "변경 사항을 기기에 저장하지 못했습니다."));}persist();render();}
function detail(id){const p=allPosts().find(p=>p.id===id);if(!p)return;if(p.serverCard){showCardDetails(id);return;}modal(`<div class="eyebrow">${esc(categoryLabel(p.category))} · ${p.sample?t("SAMPLE PROFILE", "HỒ SƠ MẪU", "예시 프로필"):t("UNVERIFIED", "CHƯA XÁC MINH", "미인증")}</div><h2>${esc(p.title)}</h2><p>${esc(p.name)} · ${esc(p.city||t("Location not provided", "Chưa cung cấp địa điểm", "지역 정보 없음"))}</p><p class="detail-story">${esc(p.story)}</p><div class="info-box">${t("Debt:", "Khoản nợ:", "부채:")} <strong>${money(p.amount)}</strong><br>${t("Pledged:", "Cam kết:", "지원 약속:")} ${money(p.pledged)} · ${t('Unpaid', 'Chưa thanh toán', '미결제')}</div>${p.sample?`<p>${t("This sample story illustrates how the app works.", "Câu chuyện minh họa để trải nghiệm ứng dụng, không đại diện cho lời kêu gọi thật.", "앱 이용 방법을 보여 주기 위한 예시 이야기입니다.")}</p>`:''}<button class="dark" id="detail-help">${p.mine?t("Close", "Đóng", "닫기"):t("I'd like to help ♡", "Tôi muốn đồng hành ♡", "도움을 주고 싶어요 ♡")}</button>`);$('#detail-help').onclick=()=>{close();if(!p.mine)help(id);};}
function help(id){const p=allPosts().find(p=>p.id===id);if(!p)return;if(p.serverCard){showCardDetails(id);return;}const remaining=p.amount-p.pledged;if(remaining<=0){toast(t("Pledges already cover the full amount for this story.", "Câu chuyện này đã đủ cam kết.", "이 이야기의 목표 금액만큼 지원이 약속되었습니다."));return;}modal(`<div class="eyebrow">${t("A LITTLE SUPPORT", "MỘT CHÚT ĐỒNG HÀNH", "작은 응원")}</div><h2>${t(`Would you like to help ${esc(p.name)}?`, `Bạn muốn giúp ${esc(p.name)}?`, `${esc(p.name)} 님을 돕고 싶으신가요?`)}</h2><p>${esc(p.title)}</p><div class="info-box">${t("Still needed:", "Còn cần cam kết:", "남은 목표 금액:")} <strong>${money(remaining)}</strong><br>${p.sample?t("This is a sample profile. ", "Đây là hồ sơ mẫu. ", "예시 프로필입니다."):''}${t("A pledge records your intention to help. No money is collected or transferred.", "Chỉ ghi nhận ý định hỗ trợ. Không thu hoặc chuyển tiền.", "지원 약속은 도움을 주겠다는 의사를 기록합니다. 결제나 송금은 이루어지지 않습니다.")}</div><form id="pledge-form"><label for="pledge-amount">${t("Amount to pledge (VND)", "Số tiền bạn muốn cam kết (VNĐ)", "지원 약속 금액 (VND)")}</label><input id="pledge-amount" name="amount" type="number" min="1000" max="${remaining}" step="1000" value="${Math.min(100000,remaining)}" required><div class="form-error" id="form-error" role="alert"></div><button class="dark">${t("Confirm pledge · No payment yet", "Xác nhận cam kết · Chưa thanh toán", "지원 약속 확인 · 결제 없음")}</button></form>`);$('#pledge-form').onsubmit=e=>{e.preventDefault();try{const amount=Number(new FormData(e.target).get('amount'));const updated=commitment(p,amount);state.posts=state.posts.map(x=>x.id===id?{...x,pledged:updated.pledged}:x);state.pledges.push({id:crypto.randomUUID(),postId:id,title:state.posts.find(post=>post.id===id)?.title||p.title,amount,date:new Date().toISOString()});persist();close();render();toast(t("Your pledge was recorded. No money was transferred.", "Đã ghi nhận cam kết. Chưa có tiền được chuyển.", "지원 약속을 기록했습니다. 송금은 이루어지지 않았습니다."));}catch(error){$('#form-error').textContent=translateError(error.message);}};}
function renderPostForm(id){const p=allPosts().find(p=>p.id===id)||{};modal(`<div class="eyebrow">${t("FOR BROKE MEMBERS", "DÀNH CHO BROKE", "BROKE 회원 전용")}</div><h2>${id?t("Edit your story", "Chỉnh sửa câu chuyện", "이야기 수정"):t("Everyone needs a hand sometimes.", "Ai cũng có lúc cần một bàn tay.", "누구에게나 도움이 필요한 순간이 있습니다.")}</h2><p>${t("Share under a nickname. In this demo, the post is saved only in your browser.", "Chia sẻ bằng biệt danh. Bài đăng này chỉ được lưu trên trình duyệt của bạn trong bản thử nghiệm.", "닉네임으로 공유하세요. 체험판에서는 게시물이 현재 브라우저에만 저장됩니다.")}</p><form id="post-form"><label for="post-name">${t("Display name or nickname", "Tên hiển thị / biệt danh", "표시 이름 또는 닉네임")}</label><input id="post-name" name="name" maxlength="50" required value="${esc(p.name||'')}"><label for="post-city">${t("City (optional)", "Thành phố (không bắt buộc)", "도시 (선택 사항)")}</label><input id="post-city" name="city" maxlength="60" value="${esc(p.city||'')}"><label for="post-title">${t("Story title", "Tiêu đề câu chuyện", "이야기 제목")}</label><input id="post-title" name="title" maxlength="100" required value="${esc(p.title||'')}"><label for="post-category">${t("Debt category", "Loại khoản nợ", "부채 유형")}</label><select name="category" id="post-category">${categories.slice(1).map(c=>`<option value="${esc(c)}" ${p.category===c?'selected':''}>${esc(categoryLabel(c))}</option>`).join('')}</select><label for="post-amount">${t("Total debt (VND)", "Tổng khoản nợ (VNĐ)", "총 부채 (VND)")}</label><input id="post-amount" name="amount" type="number" min="${Math.max(1000,p.pledged||0)}" max="1000000000000" step="1000" required value="${p.amount||''}"><label for="post-story">${t("Your story", "Câu chuyện của bạn", "내 이야기")}</label><textarea id="post-story" name="story" maxlength="3000" required placeholder="${t("What happened, and how would support help you?", "Điều gì đã xảy ra và sự hỗ trợ sẽ giúp bạn thế nào?", "어떤 일이 있었고 어떤 도움이 필요한가요?")}">${esc(p.story||'')}</textarea><div class="info-box">${t("Keep ID numbers, street addresses, card details, and account numbers private. Verification will be available later.", "Không đăng CCCD, địa chỉ cụ thể, thông tin thẻ hoặc số tài khoản. Chức năng xác minh sẽ được bổ sung sau.", "신분증 번호, 상세 주소, 카드 정보, 계좌번호는 공개하지 마세요. 인증 기능은 추후 제공됩니다.")}</div><div id="form-error" class="form-error" role="alert"></div><button class="dark">${id?t("Save changes", "Lưu thay đổi", "변경 사항 저장"):t("Post your story", "Đăng câu chuyện", "이야기 게시")}</button></form>`);$('#post-form').onsubmit=e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target));d.amount=Number(d.amount);for(const k of ['name','city','title','story'])d[k]=d[k].trim();validatePost(d);if(d.amount<(p.pledged||0))throw Error(t("The debt amount can't be lower than the total pledged.", "Số nợ không thể thấp hơn tổng cam kết.", "부채 금액은 총 지원 약속 금액보다 낮을 수 없습니다."));if(id)state.posts=state.posts.map(x=>x.id===id?{...x,...d}:x);else state.posts.unshift({...d,id:crypto.randomUUID(),pledged:0,mine:true,sample:false});state.role='Broke';persist();view='mine';close();render();toast(id?t("Changes saved.", "Đã lưu thay đổi.", "변경 사항을 저장했습니다."):t("Your post was saved on this device.", "Đã lưu bài đăng trên thiết bị của bạn.", "게시물을 이 기기에 저장했습니다."));}catch(error){$('#form-error').textContent=translateError(error.message);}};}
function deletePost(id){const p=state.posts.find(p=>p.id===id&&p.mine);if(!p)return;modal(`<h2>${t("Delete this story?", "Xóa câu chuyện này?", "이 이야기를 삭제하시겠어요?")}</h2><p>${esc(p.title)}</p><p>${t("The post will be deleted from this device.", "Bài đăng sẽ bị xóa khỏi thiết bị này.", "이 기기에서 게시물이 삭제됩니다.")}</p><button id="confirm-delete" class="dark">${t("Delete post", "Xóa bài đăng", "게시물 삭제")}</button>`);$('#confirm-delete').onclick=()=>{state.posts=state.posts.filter(x=>x.id!==id);state.saved=state.saved.filter(x=>x!==id);persist();close();render();toast(t("Post deleted.", "Đã xóa bài đăng.", "게시물을 삭제했습니다."));};}
function cancelPledge(id){const p=state.pledges.find(x=>x.id===id);if(!p)return;modal(`<h2>${t(`Cancel your pledge of ${money(p.amount)}?`, `Hủy cam kết ${money(p.amount)}?`, `${money(p.amount)} 지원 약속을 취소하시겠어요?`)}</h2><p>${esc(p.title)}</p><p>${t("No payment was made, so there's nothing to refund.", "Không có khoản tiền nào cần hoàn trả vì chưa thực hiện thanh toán.", "결제된 금액이 없어 환불할 금액이 없습니다.")}</p><button class="dark" id="confirm-cancel">${t("Confirm cancellation", "Xác nhận hủy cam kết", "지원 약속 취소 확인")}</button>`);$('#confirm-cancel').onclick=()=>{state.posts=state.posts.map(x=>x.id===p.postId?{...x,pledged:Math.max(0,x.pledged-p.amount)}:x);state.pledges=state.pledges.filter(x=>x.id!==id);persist();close();render();toast(t("Pledge canceled.", "Đã hủy cam kết.", "지원 약속을 취소했습니다."));};}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action],[data-view],[data-category]');if(!b)return;if(b.dataset.view){view=b.dataset.view;render();return;}if(b.dataset.category){category=b.dataset.category;render();return;}const id=b.dataset.id;switch(b.dataset.action){case 'save':save(id);break;case 'detail':detail(id);break;case 'help':help(id);break;case 'skip':skip();break;case 'reset':state.skipped=[];lastSkipped=null;persist();render();break;case 'undo':if(lastSkipped){state.skipped=state.skipped.filter(x=>x!==lastSkipped);lastSkipped=null;persist();render();}break;case 'discover':view='discover';category='Tất cả';query='';$('#search').value='';render();break;case 'new':postForm();break;case 'edit':postForm(id);break;case 'delete':deletePost(id);break;case 'cancel':cancelPledge(id);}});
$('#search').oninput=e=>{query=e.target.value;render();};$('#new-post').onclick=()=>postForm();$('#role-toggle').onclick=()=>{state.role=state.role==='Bros'?'Broke':'Bros';view=state.role==='Broke'?'mine':'discover';persist();render();};$('#about').onclick=()=>modal(`<div class="eyebrow">${t("WELCOME TO DEBTFREELATELY", "WELCOME TO DEBTFREELATELY", "DEBTFREELATELY에 오신 것을 환영합니다")}</div><h2>${t("Share the load together.", "Cùng nhau nhẹ gánh.", "함께 짐을 덜어요.")}</h2><p><strong>Broke</strong> ${t("members share their stories and debts.", "chia sẻ câu chuyện và khoản nợ.", "회원은 이야기와 부채를 공유합니다.")} <strong>Bros</strong> ${t("members swipe to discover stories, save them, or pledge support.", "quẹt thẻ để khám phá, lưu lại hoặc cam kết giúp một phần.", "회원은 스와이프하여 이야기를 둘러보고 저장하거나 지원을 약속할 수 있습니다.")}</p><p>${t("Swipe left to skip or right to see ways to help. On a computer, you can also use the arrow keys.", "Quẹt trái để bỏ qua, quẹt phải để mở xác nhận hỗ trợ. Trên máy tính, bạn cũng có thể dùng phím mũi tên.", "왼쪽으로 밀면 건너뛰고 오른쪽으로 밀면 지원 방법이 열립니다. 컴퓨터에서는 화살표 키도 사용할 수 있습니다.")}</p><div class="info-box">${t("In this demo, local posts and pledges are saved in this browser. Sample profiles are labeled, and pledges don't move money.", "Bản thử nghiệm: dữ liệu chỉ lưu tại trình duyệt này, chưa đồng bộ giữa người dùng. Không có đăng nhập, xác minh hoặc thanh toán thật. Hồ sơ mẫu được ghi rõ trên thẻ.", "체험판의 게시물과 지원 약속은 이 브라우저에 저장됩니다. 예시 프로필은 표시되며 지원 약속으로 결제되지는 않습니다.")}</div><p>${t("Cancel a pledge under “My pledges.” Edit or delete a post under “My posts.”", "Cam kết có thể hủy trong mục “Cam kết của tôi”. Bài viết có thể sửa hoặc xóa trong “Bài đăng của tôi”.", "‘내 지원 약속’에서 약속을 취소하고 ‘내 게시물’에서 글을 수정하거나 삭제할 수 있습니다.")}</p>`);
document.addEventListener('keydown',e=>{if(document.body.classList.contains('card-wizard-mode')||document.body.classList.contains('debts-mode')||document.body.classList.contains('bros-join-mode')||document.body.classList.contains('registration-mode')||document.body.classList.contains('messages-mode')||document.body.classList.contains('broke-mode')||document.body.classList.contains('onboarding')||$('#modal').open||e.target.matches('input,textarea,select')||view!=='discover')return;if(e.key==='ArrowLeft'){e.preventDefault();skip();}if(e.key==='ArrowRight'&&current){e.preventDefault();help(current.id);}});render();if(!storageOK)toast(t("Browser storage is unavailable. Data will last for this session only.", "Bộ nhớ trình duyệt không khả dụng; dữ liệu chỉ tồn tại trong phiên này.", "브라우저 저장소를 사용할 수 없어 데이터가 현재 세션에서만 유지됩니다."));
function showWelcome(){void refreshAdminNavigation();document.body.classList.remove('messages-mode','registration-mode','bros-join-mode','debts-mode','card-wizard-mode');hideBroke();document.body.classList.add('onboarding');document.querySelector('[data-role="Broke"]').focus();window.scrollTo(0,0);}
document.querySelectorAll('[data-role]').forEach(button=>button.addEventListener('click',()=>{if(button.dataset.role==='Broke'){showBroke();return;}if(button.dataset.role==='Bros'){showBros();return;}state.role=button.dataset.role;view=state.role==='Broke'?'mine':'discover';persist();render();document.body.classList.remove('onboarding');window.scrollTo(0,0);document.querySelector('nav .active').focus({preventScroll:true});}));
$('#choose-role').onclick=showWelcome;
$('#role-toggle').onclick=showWelcome;

initBroke({modal,close,toast,supporterMessage:openSupporterMessage,createCard:createDebtCard,discover:()=>{view='discover';category='Tất cả';query='';render();hideBroke();window.scrollTo(0,0);},saved:openSavedCards,logout:logoutRegistration,messages:showMessages,role:showWelcome,post:()=>postForm(),posts:showDebts,getPosts:()=>state.posts.filter(p=>p.mine)});

$('#profile-nav').onclick=openBrokeProfile;
$('#modal').addEventListener('close',()=>{if(document.body.classList.contains('debts-mode'))renderDebts();else if(document.body.classList.contains('broke-mode'))openBrokeProfile();});
initMessages({modal,close,toast,getRole:()=>state.role,role:showWelcome,profile:openBrokeProfile,discover:()=>{view='discover';render();}});
$('#messages-nav').onclick=showMessages;
function showBroke(){requireRegistration(user=>{activateSavedAccount(user.id);state.role='Broke';view='mine';persist();render();showCardWizard(user);});}
initRegistration({back:showWelcome,toast});

function postForm(id){requireRegistration(user=>{state.role='Broke';view='mine';persist();render();if(document.body.classList.contains('debts-mode'))showDebts();else displayBroke(user);renderPostForm(id);});}
function enterDiscover(user){
 activateSavedAccount(user.id);
 state.role=user.role;
 view='discover';
 category='Tất cả';
 query='';
 persist();
 hideBroke();
 document.body.classList.remove('onboarding','registration-mode','bros-join-mode','messages-mode','debts-mode','card-wizard-mode');
 render();
 $('#role-name').textContent=user.name;
 window.scrollTo(0,0);
}
initWelcomeLogin(enterDiscover);
function showBros(){showBrosJoin(enterDiscover);}
initBrosJoin({back:showWelcome,toast,full:callback=>requireRegistration(callback,'Bros')});
$('#logout-nav').onclick=logoutRegistration;
function openBrokeProfile(){const selectedRole=state.role;const open=user=>{activateSavedAccount(user.id);document.body.classList.remove('onboarding','registration-mode','bros-join-mode','messages-mode','debts-mode','card-wizard-mode','swipe-page');state.role=selectedRole;render();displayBroke({...user,role:selectedRole});};if(selectedRole==='Bros'){fetch('/api/auth/me',{credentials:'same-origin'}).then(async response=>{if(!response.ok)throw Error();const {user}=await response.json();open(user);}).catch(()=>showBrosJoin(open));}else requireRegistration(open);}
initDebts({getPosts:()=>state.posts.filter(p=>p.mine),modal,close,profile:openBrokeProfile,messages:showMessages,back:showWelcome,add:()=>postForm(),edit:postForm,remove:deletePost});
initCardWizard({back:showWelcome,profile:openBrokeProfile,debts:showDebts,modal,close,toast,contact:openCardConversation});
document.addEventListener('click',event=>{const b=event.target.closest('#content [data-dc]');if(!b)return;if(b.dataset.dc==='skip'){if(view==='saved')b.closest('.saved-card-item')?.remove();else skip(b.dataset.id);}if(b.dataset.dc==='save'){if(b.dataset.id.startsWith('preview:')){const items=previewStore();delete items[b.dataset.id.slice(8)];try{localStorage.setItem(savedPreviewsKey(activeUserId),JSON.stringify(items));render();}catch{toast(t("Changes couldn't be saved.", "Không lưu được thay đổi.", "변경 사항을 저장하지 못했습니다."));}}else save(b.dataset.id);}if(b.dataset.dc==='read'){const card=cardById(b.dataset.id);if(card)modal(cardDetailsHTML(card));}if(b.dataset.dc==='detail')showCardDetails(b.dataset.id);});
$('.user').setAttribute('role','button');$('.user').setAttribute('tabindex','0');$('.user').setAttribute('aria-label',t("Open your profile", "Mở trang cá nhân", "프로필 열기"));
function brosProfile(){openBrokeProfile();}
$('.user').addEventListener('click',event=>{if(!event.target.closest('#role-toggle'))brosProfile();});$('.user').addEventListener('keydown',event=>{if((event.key==='Enter'||event.key===' ')&&event.target===$('.user')){event.preventDefault();brosProfile();}});
$('.header-brand').addEventListener('click',event=>{event.preventDefault();brosProfile();});

const swipeBack=document.createElement('button');swipeBack.className='swipe-profile-back';swipeBack.textContent=t("← Back to your profile", "← Quay lại trang cá nhân", "← 프로필로 돌아가기");swipeBack.onclick=openBrokeProfile;document.querySelector('.main>header').append(swipeBack);



function createDebtCard(){if(state.role==='Bros'){fetch('/api/auth/me',{credentials:'same-origin'}).then(async response=>{if(!response.ok)throw Error();const {user}=await response.json();startNewDebtCard(user);}).catch(()=>showBrosJoin(startNewDebtCard));}else requireRegistration(startNewDebtCard);}


function activateSavedAccount(id){if(!id||activeUserId===id)return;activeUserId=id;try{const key=savedIdsKey(id),legacyOwner=localStorage.getItem('debtfreelately-legacy-saved-owner');if(!legacyOwner&&localStorage.getItem(key)===null){localStorage.setItem(key,JSON.stringify(state.saved));const old=localStorage.getItem('debtfreelately-saved-card-previews');if(old)localStorage.setItem(savedPreviewsKey(id),old);localStorage.setItem('debtfreelately-legacy-saved-owner',id);}state.saved=JSON.parse(localStorage.getItem(key)||'[]');if(!Array.isArray(state.saved))state.saved=[];}catch{state.saved=[];toast(t("We couldn't load your saved cards.", "Không đọc được danh sách đã lưu của tài khoản.", "저장한 카드를 불러오지 못했습니다."));}}
function communitySummary() {
 const count = allPosts().filter(post => !post.mine).length;
 const saved = getRemainingSaved().length;
 return t(`Stories available: ${count}. Saved cards: ${saved}.`, `Số câu chuyện: ${count}. Số thẻ đã lưu: ${saved}.`, `볼 수 있는 이야기 ${count}개, 저장한 카드 ${saved}장.`);
}
const discoverNav=document.createElement('nav');discoverNav.className='discover-main-nav';discoverNav.setAttribute('aria-label',t("Discover navigation", "Điều hướng khám phá", "둘러보기 메뉴"));discoverNav.innerHTML=[['home',t("Home", "Home", "홈")],['discover',t("Discover", "Discover", "둘러보기")],['community',t("Community", "Community", "커뮤니티")],['debts',t("My Debts", "My Debts", "내 부채")],['messages',t("Messages", "Messages", "메시지")]].map(([action,label])=>`<button data-discover="${action}" class="${action==='discover'?'selected':''}">${di(action)}<span>${label}</span></button>`).join('');discoverNav.insertAdjacentHTML('beforeend',`<button data-notifications type="button">♧ <span>${t("Notifications", "Thông báo", "알림")}</span></button>`);document.querySelector('.main>header').append(discoverNav);discoverNav.addEventListener('click',event=>{const b=event.target.closest('[data-discover]');if(!b)return;switch(b.dataset.discover){case 'home':openBrokeProfile();break;case 'discover':view='discover';render();break;case 'community':modal(`<div class="eyebrow">${t("OUR COMMUNITY", "OUR COMMUNITY", "우리 커뮤니티")}</div><h2>${t("Share the load together.", "Cùng nhau nhẹ gánh.", "함께 짐을 덜어요.")}</h2><p>${communitySummary()}</p><div class="info-box">${t("Live community activity, debt verification, and payments are unavailable in this demo.", "Bản thử nghiệm chưa có dữ liệu cộng đồng trực tiếp, xác minh khoản nợ hoặc thanh toán thật.", "체험판에서는 실시간 커뮤니티 활동, 부채 검증, 결제를 이용할 수 없습니다.")}</div>`);$('#modal').dataset.adCommunity='true';break;case 'debts':showDebts();break;case 'messages':showMessages();break;}});


let loadingPublished=false;
async function refreshPublished(){if(loadingPublished)return;loadingPublished=true;try{const r=await fetch('/api/cards',{credentials:'same-origin',cache:'no-store'});if(!r.ok)throw Error(t("We couldn't load the approved cards.", "Không tải được các thẻ đã duyệt.", "승인된 카드를 불러오지 못했습니다."));const {cards}=await r.json();approvedPosts=cards.map(item=>({id:item.id,name:item.card.name,title:item.card.debts.map(d=>d.title).join(' · '),story:item.card.debts.map(d=>d.story||'').join('\n'),pledged:0,category:'Khác',mine:false,sample:false,approved:true,serverCard:item.card}));if(view==='discover'||view==='saved')render();}catch{approvedPosts=[];if(view==='discover'||view==='saved')render();toast(t("We couldn't load the approved cards. Refresh the page to try again.", "Chưa tải được thẻ đã duyệt. Vui lòng tải lại trang.", "승인된 카드를 불러오지 못했습니다. 페이지를 새로고침해 주세요."));}finally{loadingPublished=false;}}
refreshPublished();
window.addEventListener('focus',refreshPublished);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshPublished();});
setInterval(()=>{if(!document.hidden)refreshPublished();},30000);

initHowItWorks({Broke:showBroke,Bros:showBros});

initMemberNotifications({modal,toast});

initAdvertising();

async function restoreSession(){
 if(location.hash==='#how-it-works')return;
 const welcome=$('#welcome');
 let interacted=false;
 const markInteraction=()=>{interacted=true;};
 welcome.addEventListener('click',markInteraction,{capture:true,once:true});
 try{
  const {user}=await authRequest('me');
  if(user&&!interacted&&!location.hash&&document.body.classList.contains('onboarding'))enterDiscover(user);
 }catch{
  // Visitors without a valid session can use the welcome screen.
 }finally{
  welcome.removeEventListener('click',markInteraction,true);
 }
}

void restoreSession();
